import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { LinkButtonProps } from "./link-button.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "LinkButton";

// Generate child element class names for the component, should match available style slots
export const LinkButtonClasses = {
  root: "exp-textura_link-button",
  sm: "exp-textura_link-button_sm",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  secondary: {
    root: {
      color: theme.buttonLink.secondary.color.content.enabled,
      textDecoration: "underline",
    },
    hover: {
      color: theme.buttonLink.secondary.color.content.hover,
      textDecoration: "none",
    },
    pressed: {
      color: theme.buttonLink.secondary.color.content.pressed,
      textDecoration: "underline",
    },
    disabled: {
      color: theme.buttonLink.secondary.color.content.disabled,
      textDecoration: "underline",
    },
  },
});

const generateStyles = (
  props: LinkButtonProps<React.ElementType> & { currentTheme: Theme },
): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<LinkButtonProps<React.ElementType>["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",
    background: "none",
    border: "none",
    cursor: "pointer",
    height: theme.toRem(20),
    alignItems: "center",
    justifyContent: "center",
    textAlign: "center",
    gap: theme.toRem(theme.spacing[8]),
    textDecoration: "none",
    padding: "0px",
    color: theme.buttonLink.primary.color.content.enabled,
    ...theme.typography.label.md,

    "&:hover:not([data-disabled='true'])": {
      color: theme.buttonLink.primary.color.content.hover,
      textDecoration: "underline",
      ...styleSlots?.hover,
    },

    "&:active:not([data-disabled='true'])": {
      color: theme.buttonLink.primary.color.content.pressed,
      ...styleSlots?.pressed,
    },

    "&:disabled, &:disabled:hover, &[data-disabled='true']": {
      cursor: "not-allowed",
      color: theme.buttonLink.primary.color.content.disabled,
      textDecoration: "none",
      ...styleSlots?.disabled,
    },

    "&:focus-visible": {
      ...theme.focusRing,
      ...styleSlots?.focus,
    },

    [`&.${LinkButtonClasses.sm}`]: {
      height: theme.toRem(16),
      fontSize: theme.typography.label.sm.fontSize,
      ...styleSlots?.sm,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledLinkButton = styled("button", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<LinkButtonProps<React.ElementType> & { currentTheme: Theme }>((props) => generateStyles(props));
